                    y,x=stack.pop(); cells.add((y,x))
                    for dy,dx in((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and gi[ny][nx]==0 and (ny,nx) not in seen:
